from dataclasses import dataclass
from typing import Callable

@dataclass
class Tool:
    name: str
    desc: str
    fn: Callable

{{registry_name}}: dict[str, Tool] = {}

def tool(desc: str):
    def deco(fn: Callable):
        {{registry_name}}[fn.__name__] = Tool(fn.__name__, desc, fn)
        return fn
    return deco

@tool("add two numbers")
def add(a: int, b: int) -> int:
    return a + b

def call(name: str, **kw):
    return {{registry_name}}[name].fn(**kw)

if __name__ == "__main__":
    print(call("add", a=1, b=2))
